"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

_ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = goal = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == "S":
                start = (r, c)
            elif ch == "G":
                goal = (r, c)
    if start is None or goal is None:
        return None

    def cost(cell: Cell) -> int:
        return _ENTER_COST[grid[cell[0]][cell[1]]]

    # Dijkstra: uniform-cost search; ties broken by cell order for determinism.
    dist = {start: cost(start)}
    prev: dict[Cell, Cell] = {}
    queue = [(cost(start), start)]
    settled: set[Cell] = set()
    while queue:
        d, cell = heapq.heappop(queue)
        if cell in settled:
            continue
        settled.add(cell)
        if cell == goal:
            path = [cell]
            while cell in prev:
                cell = prev[cell]
                path.append(cell)
            return path[::-1]
        r, c = cell
        for nxt in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if not (0 <= nxt[0] < len(grid) and 0 <= nxt[1] < len(grid[nxt[0]])):
                continue
            if grid[nxt[0]][nxt[1]] == "#":
                continue
            nd = d + cost(nxt)
            if nd < dist.get(nxt, float("inf")):
                dist[nxt] = nd
                prev[nxt] = cell
                heapq.heappush(queue, (nd, nxt))
    return None
